// Obtiene los datos de entrada del nodo anterior
const items = $input.all();
const filteredItems = [];

// Define la extensión de archivo que se quiere permitir
const ALLOWED_EXTENSION = 'xlsx';

for (const item of items) {
    // Itera sobre todos los archivos adjuntos en el ítem actual
    const binaryData = item.binary;

    if (binaryData) {
        // Objeto para almacenar solo el archivo XLSX filtrado y renombrado
        const filteredBinary = {};

        // Recorre cada archivo en el objeto binario
        for (const fileName in binaryData) {
            if (binaryData.hasOwnProperty(fileName)) {

                const file = binaryData[fileName];

                // 1. Obtiene el nombre real del archivo
                const actualFileName = file.fileName || fileName;

                // 2. Extrae la extensión del archivo (última parte después del punto)
                const extension = actualFileName.split('.').pop().toLowerCase();

                // 3. Compara la extensión
                if (extension === ALLOWED_EXTENSION) {
                    // Si es XLSX, lo agrega al objeto binario filtrado
                    // *** CORRECCIÓN: Renombra la clave del archivo binario a "data" ***

                    // Clonamos el objeto de archivo para mantener todas sus propiedades (mimeType, data, etc.)
                    // y nos aseguramos de que el nombre del archivo (propiedad 'fileName' dentro del objeto) 
                    // se mantenga con el nombre original, pero la CLAVE BINARIA se llama 'data'.

                    const renamedFile = { ...file };
                    // El nuevo nombre clave en el objeto 'binary' será "data"
                    filteredBinary['data'] = renamedFile;

                    // Dado que n8n solo necesita un archivo para continuar el proceso,
                    // y ya encontramos el XLSX, podemos salir del bucle interno
                    break;
                }
            }
        }

        // Si se encontró y renombró el archivo XLSX, se crea un nuevo ítem de salida
        if (Object.keys(filteredBinary).length > 0) {
            // Se clona el ítem de datos para mantener los campos JSON
            const newItem = JSON.parse(JSON.stringify(item.json));

            // Se agrega el objeto binario filtrado (que ahora contiene 'data') al nuevo ítem
            filteredItems.push({
                json: newItem,
                binary: filteredBinary
            });
        }
    }
}

// Retorna los ítems que contienen solo el archivo XLSX renombrado como "data"
return filteredItems;

const items = $input.all();
const outputItems = [];

let fechaDesdeSQL = null;
let fechaHastaSQL = null;

// --- 1. CONFIGURACIÓN DE BÚSQUEDA ---

// Función auxiliar para convertir el formato DD/MM/YYYY a YYYY-MM-DD
function formatToSQL(dateString) {
    if (!dateString) return null;
    const parts = dateString.split('/');
    if (parts.length === 3) {
        return `${parts[2]}-${parts[1]}-${parts[0]}`;
    }
    return null; 
}

// Expresión Regular para buscar CUALQUIER patrón DD/MM/AAAA.
// Se añade 'g' (global) para que encuentre TODAS las fechas en una misma celda.
const regexFecha = /(\d{2}\/\d{2}\/\d{4})/g;

// Palabras clave para identificar el TIPO de fecha (en minúsculas)
// Puedes añadir más si es necesario (ej: 'comienzo', 'término')
const KEYWORDS_DESDE = ['desde', 'inicio', 'del'];
const KEYWORDS_HASTA = ['hasta', 'fin', 'al'];


// --- 2. BUCLE DE BÚSQUEDA ROBUSTO ---
// Itera las filas SÓLO hasta encontrar ambas fechas.
for (const item of items) {
    const json = item.json;

    // Iterar sobre TODAS las celdas (valores de columna) de esta fila
    // Object.values(json) nos da un array con el contenido de todas las columnas de esa fila
    for (const cellValue of Object.values(json)) {
        
        // Si la celda está vacía o ya encontramos todo, saltar
        if (!cellValue || (fechaDesdeSQL && fechaHastaSQL)) continue;

        let valor = String(cellValue).trim();
        let valorLower = valor.toLowerCase(); // Para buscar keywords
        
        // Usar matchAll() para encontrar TODAS las fechas en la celda
        const matches = [...valor.matchAll(regexFecha)];

        // Si no hay fechas en esta celda, ir a la siguiente celda
        if (matches.length === 0) continue;

        // --- Lógica de Asignación por Keywords ---
        const esDesde = KEYWORDS_DESDE.some(keyword => valorLower.includes(keyword));
        const esHasta = KEYWORDS_HASTA.some(keyword => valorLower.includes(keyword));

        // Caso 1: Celda contiene "Desde" (y no "Hasta") y al menos una fecha
        // Ej: "Período desde: 30/09/2025"
        if (esDesde && !esHasta && !fechaDesdeSQL) {
            fechaDesdeSQL = formatToSQL(matches[0][1]); // Usar la primera fecha encontrada
        }

        // Caso 2: Celda contiene "Hasta" (y no "Desde") y al menos una fecha
        // Ej: "Fecha hasta 07/10/2025"
        if (esHasta && !esDesde && !fechaHastaSQL) {
            fechaHastaSQL = formatToSQL(matches[0][1]); // Usar la primera fecha encontrada
        }

        // Caso 3: Celda contiene AMBAS keywords (y al menos 2 fechas)
        // Ej: "Período del 30/09/2025 al 07/10/2025"
        if (esDesde && esHasta && matches.length >= 2) {
            if (!fechaDesdeSQL) {
                fechaDesdeSQL = formatToSQL(matches[0][1]); // Asumir la primera es 'desde'
            }
            if (!fechaHastaSQL) {
                fechaHastaSQL = formatToSQL(matches[1][1]); // Asumir la segunda es 'hasta'
            }
        }
    } // Fin del bucle de celdas (columnas)
    
    // Detenemos la búsqueda de FILAS si ambas fechas ya fueron encontradas
    if (fechaDesdeSQL && fechaHastaSQL) {
        break; 
    }
} // Fin del bucle de filas

// --- 3. BUCLE PARA AÑADIR LAS FECHAS (Idéntico al original) ---
// Ahora que tenemos las fechas, las añadimos a CADA fila.
for (const item of items) {
    const newItem = {
        ...item.json, 
        fecha_inicio_sql: fechaDesdeSQL, 
        fecha_fin_sql: fechaHastaSQL,
    };

    outputItems.push({ json: newItem, binary: item.binary });
}

return outputItems;

