const items = $input.all();
let outputItems = []; // Declarado con let

// Si no hay entrada, no hay salida
if (items.length === 0) {
    return [];
}

// --- 1. CONFIGURACIÓN ---
// Nombres de columna que BUSCAMOS (en minúsculas)
const KEY_RUT = 'rut';
const KEY_NOMBRE = 'nombrecliente';
const KEY_CORREO = 'correo';
const KEY_FECHA = 'fecha';
const KEY_IMPORTE = 'importe';
const KEY_ID_CLIENTE = 'idcliente';

// ***** TOPE MÁXIMO DE FACTURAS *****
// 170 columnas totales - 4 (RUT, Nombre, Correo, ID) = 166 columnas.
// 166 / 2 (fecha e importe) = 83 facturas.
const MAX_FACTURAS_PERMITIDAS = 15;
// **********************************

// --- 2. DETECCIÓN DE COLUMNAS (Anti-errores de Mayúsculas) ---
let COL_RUT, COL_NOMBRE, COL_CORREO, COL_FECHA, COL_IMPORTE, COL_ID_CLIENTE;
const firstItemJson = items[0].json;
const allKeys = Object.keys(firstItemJson);

function findKey(keyName) {
    const foundKey = allKeys.find(k => k.toLowerCase() === keyName.toLowerCase());
    if (!foundKey && (keyName === KEY_RUT || keyName === KEY_ID_CLIENTE)) {
        throw new Error(`¡Error Crítico! No se encontró la columna "${keyName}". Verifique su consulta SQL.`);
    }
    return foundKey;
}

try {
    COL_RUT = findKey(KEY_RUT);
    COL_NOMBRE = findKey(KEY_NOMBRE);
    COL_CORREO = findKey(KEY_CORREO);
    COL_FECHA = findKey(KEY_FECHA);
    COL_IMPORTE = findKey(KEY_IMPORTE);
    COL_ID_CLIENTE = findKey(KEY_ID_CLIENTE); 
} catch (error) {
    return [{ json: { error: error.message } }];
}

// Regex para limpiar el RUT
const regexLimpiezaRut = /[.-]/g; 

// Almacén para agrupar
const groupedItems = new Map();
let maxFacturas = 0; 

// --- BUCLE 1: LIMPIAR, AGRUPAR Y APLANAR ---
for (const item of items) {
    const json = item.json;
    let rutLimpio = null;
    let groupingKey = null; 

    // 1. Limpiar el RUT
    if (json[COL_RUT]) { 
        const rutSucio = String(json[COL_RUT]);
        rutLimpio = rutSucio.replace(regexLimpiezaRut, '');
    }
    
    delete json[COL_RUT]; 
    json.RUT = rutLimpio; 

    // 2. Obtener la LLAVE DE AGRUPACIÓN (ID Cliente)
    if (json[COL_ID_CLIENTE] !== null && json[COL_ID_CLIENTE] !== undefined) { 
        groupingKey = String(json[COL_ID_CLIENTE]).trim(); 
    } else {
        groupingKey = null;
    }

    // **FILTRO IMPORTANTE (Soluciona la causa raíz)**
    // Ignorar nulos, vacíos ("") y "0"
    if (!groupingKey || groupingKey === '0') { 
        continue; // ESTO EVITA LAS COLUMNAS FANTASMA
    }

    // 3. Agrupar
    if (groupedItems.has(groupingKey)) {
        const existing = groupedItems.get(groupingKey);
        existing.count++; 
        
        // **FILTRO DE TOPE (Soluciona el síntoma)**
        // Si este cliente ya superó el límite, no añadir más columnas
        if (existing.count > MAX_FACTURAS_PERMITIDAS) {
            continue; 
        }
        
        existing.json['fecha_' + existing.count] = json[COL_FECHA];
        existing.json['importe_' + existing.count] = json[COL_IMPORTE];
        
        // El máximo de facturas de la tabla NUNCA superará el tope
        if (existing.count > maxFacturas) {
            maxFacturas = existing.count;
        }
    
    } else {
        // CLIENTE NUEVO
        const newRow = {};
        newRow.nombrecliente = json[COL_NOMBRE];
        newRow.RUT = rutLimpio; 
        newRow.correo = json[COL_CORREO];
        newRow[KEY_ID_CLIENTE] = groupingKey; 
        
        newRow.fecha_1 = json[COL_FECHA];
        newRow.importe_1 = json[COL_IMPORTE];
        
        groupedItems.set(groupingKey, { json: newRow, count: 1 });
        
        if (maxFacturas === 0) {
            maxFacturas = 1;
        }
    }
}

// --- BUCLE 2: RELLENAR (PADDEAR) CON CEROS ---
// (maxFacturas ahora está limitado a 83)
for (const entry of groupedItems.values()) {
    const json = entry.json;
    const count = entry.count; 

    // Rellenar solo hasta el máximo (ej: 83)
    for (let i = count + 1; i <= maxFacturas; i++) {
        const fechaKey = 'fecha_' + i;
        const importeKey = 'importe_' + i;

        json[fechaKey] = 0;
        json[importeKey] = 0;
    }
}

// --- BUCLE 3: FORMATEAR LA SALIDA ---
// (Se quita "const" para re-asignar)
outputItems = Array.from(groupedItems.values()).map(entry => ({ json: entry.json }));

return outputItems;

const items = $input.all();
const outputItems = [];

// --- LÍMITE DE SEGURIDAD ---
const MAX_FACTURAS_PARA_BUSCAR_COMBO = 20;

// --- FUNCIÓN RECURSIVA (SIN CAMBIOS) ---
function findCombinationsRecursive(facturas, pagoRestante, startIndex) {
    if (pagoRestante === 0) {
        return [];
    }
    if (pagoRestante < 0 || startIndex >= facturas.length) {
        return null;
    }
    for (let i = startIndex; i < facturas.length; i++) {
        const facturaActual = facturas[i];
        const resultado = findCombinationsRecursive(
            facturas, 
            pagoRestante - facturaActual.importeCentavos, 
            i + 1 
        );
        if (resultado !== null) {
            return [facturaActual, ...resultado];
        }
    }
    return null;
}

// --- FUNCIÓN ENVOLTORIO (SIN CAMBIOS) ---
function findMatchingFacturas(facturas, pagoTotal) {
    const pagoCentavos = Math.round(parseFloat(pagoTotal) * 100);
    if (pagoCentavos === 0) return [];
    const margenCentavos = 100; 
    for (let i = 0; i < facturas.length; i++) {
        const diferencia = Math.abs(facturas[i].importeCentavos - pagoCentavos);
        if (diferencia <= margenCentavos) {
            return [facturas[i]]; 
        }
    }
    if (facturas.length > MAX_FACTURAS_PARA_BUSCAR_COMBO) {
        return null; 
    }
    const resultado = findCombinationsRecursive(facturas, pagoCentavos, 0);
    return resultado || []; 
}
// --- FIN DE FUNCIONES AUXILIARES ---

// --- BUCLE PRINCIPAL (SOBRE FILAS DEL MERGE) ---
for (const item of items) {
    const json = item.json;
    const pagoTransferencia = Math.abs(parseFloat(json.monto_transferencia) || 0);
    const facturas = [];
    let deuda_total_original = 0;
    let facturaMasBarata = Infinity;

    const importeKeys = Object.keys(json)
        .filter(key => key.startsWith('importe_'))
        .sort((a, b) => parseInt(a.split('_')[1]) - parseInt(b.split('_')[1]));

    for (const importeKey of importeKeys) {
        const importe = Math.abs(parseFloat(json[importeKey]) || 0);
        if (importe === 0) continue; 
        const num = importeKey.split('_')[1];
        const fechaKey = 'fecha_' + num;
        const fecha = json[fechaKey];
        facturas.push({ 
            fecha: fecha, 
            importeCentavos: Math.round(importe * 100)
        });
        deuda_total_original += importe;
        if (importe < facturaMasBarata) {
            facturaMasBarata = importe;
        }
    }

    // 3. Añadir columnas nuevas y calcular deudas
    json.deuda_total_original = Math.round(deuda_total_original * 100) / 100;
    json.deuda_restante = Math.round((deuda_total_original - pagoTransferencia) * 100) / 100;
    json.quincenas_pagadas = null; // Default

    // 4. Lógica de Coincidencia (usando las reglas que definió)
    if (pagoTransferencia === 0) {
        json.quincenas_pagadas = 'N/A (Sin Pago)';
    
    // ***** CAMBIO 1 AQUÍ *****
    } else if (pagoTransferencia < (facturaMasBarata * 0.99)) { 
    	// Antes: 'Abono Parcial (Insuficiente)'
        json.quincenas_pagadas = 'Abono Insuficiente';
    
    } else {
        const facturasPagadas = findMatchingFacturas(facturas, pagoTransferencia);

        if (facturasPagadas === null) {
            // Caso 1: Se activó el LÍMITE DE SEGURIDAD
            json.quincenas_pagadas = `Sin Coincidencia (Límite ${MAX_FACTURAS_PARA_BUSCAR_COMBO} facturas)`;
        } else if (facturasPagadas.length > 0) {
            // Caso 2: ¡Encontrado! (1 o N facturas)
            json.quincenas_pagadas = facturasPagadas.map(f => f.fecha).join(', ');
        } else {
            // ***** CAMBIO 2 AQUÍ *****
            // Antes: 'Sin Coincidencia Exacta'
            json.quincenas_pagadas = 'Abono Parcial';
        }
    }

    outputItems.push(item);
}

return outputItems;

const items = $input.all();
const outputItems = [];

// --- 1. CONFIGURACIÓN ---
// Regex para RUT Personal:
// ^[12]   -> Debe empezar con "1" o "2"
// \d{7}    -> Seguido de 7 dígitos
// [0-9Kk] -> Terminar en un número (0-9) o "K"/"k"
// $        -> Debe ser el final de la cadena (total 9 dígitos)
const regexRutPersonal = /^[12]\d{7}[0-9Kk]$/i; // 'i' para K/k

// --- 2. BUCLE FILTRADOR ---
for (const item of items) {
    const json = item.json;
    
    // Obtener el RUT que ya fue limpiado por el nodo anterior
    const rut = json.RUT;

    // Si no hay RUT, o es el RUT "0", descartar
    if (!rut || rut === "0") {
        continue;
    }

    // --- 3. Lógica de Filtro ---
    // Probar el RUT con la nueva Regex
    if (regexRutPersonal.test(rut)) {
        // Si SÍ coincide (es un RUT personal), añadirlo a la salida
        outputItems.push(item);
    }
    // Si no coincide, simplemente se ignora y no pasa.
}

return outputItems;

